CREATE TABLE plan_events (
 seq INTEGER PRIMARY KEY AUTOINCREMENT, event TEXT NOT NULL, payload TEXT NOT NULL
)

CREATE TRIGGER learning_delete_indexes AFTER DELETE ON learning_nodes
BEGIN
 DELETE FROM learning_fts WHERE id=old.id;
 DELETE FROM learning_titles WHERE id=old.id;
END

CREATE TRIGGER memory_fts_insert AFTER INSERT ON memory_items BEGIN
    INSERT INTO memory_fts(rowid, subject, key, content) VALUES (new.seq, new.subject, new.key, new.content);
END

CREATE TRIGGER memory_fts_update AFTER UPDATE OF subject, key, content ON memory_items BEGIN
    INSERT INTO memory_fts(memory_fts, rowid, subject, key, content) VALUES ('delete', old.seq, old.subject, old.key,
                                                                              old.content);
    INSERT INTO memory_fts(rowid, subject, key, content) VALUES (new.seq, new.subject, new.key, new.content);
END

CREATE TRIGGER memory_import_item_gone AFTER DELETE ON memory_items BEGIN
    DELETE FROM memory_import_items WHERE item_id = old.id;
END

CREATE TRIGGER recall_journal_gone AFTER DELETE ON journal BEGIN
    DELETE FROM chat_fts WHERE doc = 'journal:' || old.id;
    DELETE FROM recall_vectors WHERE doc = 'journal:' || old.id;
END

CREATE TRIGGER recall_vectors_added AFTER INSERT ON recall_vectors BEGIN
    UPDATE recall_state SET value = CAST(value AS INTEGER) + 1 WHERE name = 'vectors';
END

CREATE TRIGGER recall_vectors_item_gone AFTER DELETE ON memory_items BEGIN
    DELETE FROM recall_vectors WHERE doc = 'memory:' || old.id;
END

CREATE TRIGGER recall_vectors_node_gone AFTER DELETE ON learning_nodes BEGIN
    DELETE FROM recall_vectors WHERE doc = old.id;
END

CREATE TRIGGER recall_vectors_removed AFTER DELETE ON recall_vectors BEGIN
    UPDATE recall_state SET value = CAST(value AS INTEGER) + 1 WHERE name = 'vectors';
END

CREATE TRIGGER trail_fts_ad AFTER DELETE ON trail BEGIN
    DELETE FROM trail_fts WHERE rowid = old.seq;
END

CREATE TRIGGER trail_fts_ai AFTER INSERT ON trail BEGIN
    INSERT INTO trail_fts(rowid, text) VALUES (new.seq, coalesce((SELECT group_concat(value, ' ') FROM json_tree((CASE WHEN json_valid(new.data_json) THEN new.data_json ELSE '{}' END)) WHERE type = 'text'), ''));
END

CREATE TRIGGER trail_fts_au AFTER UPDATE OF data_json ON trail BEGIN
    DELETE FROM trail_fts WHERE rowid = old.seq;
    INSERT INTO trail_fts(rowid, text) VALUES (new.seq, coalesce((SELECT group_concat(value, ' ') FROM json_tree((CASE WHEN json_valid(new.data_json) THEN new.data_json ELSE '{}' END)) WHERE type = 'text'), ''));
END
